/**
 * skill-auditor.ts — L4 技能可执行性 + 安全审计
 *
 * 在 Phase D 之后、Phase E 之前运行。
 * 对生成的每个 SkillCard 执行可执行性检查和云鼎实验室安全审计。
 * 审计结果非阻塞：失败技能只记录到 notes，不中断管道。
 */
import type { SkillSetBlue } from '../types';
import { type SecurityAuditReport } from '../engine-context';
export interface SkillAuditEntry {
    skillId: string;
    skillName: string;
    roleId: string;
    executability: {
        hasScenarios: boolean;
        hasSteps: boolean;
        stepsSufficient: boolean;
        passed: boolean;
    };
    securityAudit: SecurityAuditReport | null;
    overall: 'pass' | 'warn' | 'fail';
}
export interface SkillAuditResult {
    entries: SkillAuditEntry[];
    passed: number;
    warned: number;
    failed: number;
    overallPass: boolean;
}
/** 对 Phase D 产出的所有技能执行可执行性+安全审计 */
export declare function auditSkills(skillSets: SkillSetBlue[]): SkillAuditResult;
